import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;
import org.apache.abdera.parser.ParseException;

/**
 * Secure implementation of the Atom provider.
 *
 * <p>
 * The original implementation reused a shared {@link Parser} instance and
 * configured the {@link ParserOptions} inside a synchronized block.  This
 * approach did not guarantee that the options (especially {@code
 * setResolveEntities(false)}) were applied before parsing, leaving the
 * application vulnerable to XML External Entity (XXE) attacks.
 * </p>
 *
 * <p>
 * The patched version creates a fresh {@link Parser} for each request,
 * configures a dedicated {@link ParserOptions} object with entity resolution
 * disabled **before** any parsing occurs, and avoids any shared mutable state.
 * The input stream is also closed reliably to prevent resource leaks.
 * </p>
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    /** A single, thread‑safe {@link Abdera} engine. */
    private static final Abdera ATOM_ENGINE = new Abdera();

    private boolean autodetectCharset;

    // ----------------------------------------------------------------------
    //  Patched readFrom implementation
    // ----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        /* ------------------------------------------------------------------
         * 1. Obtain a fresh parser instance.
         *
         *    The Abdera API returns a new {@link Parser} for each call to
         *    {@code getParser()}, which eliminates the need for synchronization
         *    and prevents cross‑thread contamination of parser state.
         * ------------------------------------------------------------------ */
        Parser parser = ATOM_ENGINE.getParser();

        /* ------------------------------------------------------------------
         * 2. Build a secure ParserOptions object.
         *
         *    - Autodetect charset according to the provider's configuration.
         *    - Explicitly disable entity resolution to block XXE.
         *    - Disable DTD processing if the underlying parser supports it.
         * ------------------------------------------------------------------ */
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        options.setResolveEntities(false);          // critical: block external entities
        // The following call is safe – if the implementation does not provide it,
        // it will be a no‑op at compile time because the method exists in recent
        // Abdera versions. It adds an extra layer of defence by refusing DTDs.
        try {
            options.setSupportDTD(false);
        } catch (NoSuchMethodError | UnsupportedOperationException ignored) {
            // Older Abdera versions may not expose this method; the
            // resolveEntities flag already mitigates the main risk.
        }

        /* ------------------------------------------------------------------
         * 3. Apply the options to the parser *before* parsing.
         * ------------------------------------------------------------------ */
        parser.setParserOptions(options);

        /* ------------------------------------------------------------------
         * 4. Parse the input safely.
         *
         *    Any parsing exception is wrapped as an IOException because the
         *    JAX‑RS contract only declares IOException.
         * ------------------------------------------------------------------ */
        Document<T> document;
        try {
            document = parser.parse(entityStream);
        } catch (ParseException | RuntimeException e) {
            // Convert parsing failures to a checked IOException for the caller.
            throw new IOException("Failed to parse Atom XML payload", e);
        } finally {
            // Ensure the stream is closed to avoid resource leaks.
            try {
                entityStream.close();
            } catch (IOException ignored) {
                // Nothing we can do; the stream is already being closed.
            }
        }

        /* ------------------------------------------------------------------
         * 5. Return the root element of the parsed document.
         * ------------------------------------------------------------------ */
        return document.getRoot();
    }

    // ----------------------------------------------------------------------
    // Other methods (writeTo, etc.) remain unchanged.
    // ----------------------------------------------------------------------
}
