import org.apache.commons.lang3.StringUtils;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * URLValidator – validates URL fields.
 *
 * The original implementation could return a very complex regular expression
 * when both {@code urlRegexExpression} and {@code urlRegex} were {@code null}
 * or empty.  While functionally correct, this behaviour could be abused to
 * trigger excessive back‑tracking in the regex engine, leading to a denial‑of‑
 * service (DoS).  The patched version adds explicit null/empty checks,
 * defensive parsing, logging of unexpected conditions and returns a safe,
 * lightweight default pattern when no custom regex is supplied.
 */
public class URLValidator extends FieldValidatorSupport {

    private static final Logger LOG = Logger.getLogger(URLValidator.class.getName());

    private String urlRegex;
    private String urlRegexExpression;

    // other methods ...

    /**
     * Returns a regular expression that can be used for client‑side URL validation.
     *
     * <p>Resolution strategy:
     * <ol>
     *   <li>If {@code urlRegexExpression} is non‑null and non‑empty, attempt to parse it.
     *       If parsing succeeds and yields a non‑empty {@link String}, that value is returned.
     *   </li>
     *   <li>Otherwise, if {@code urlRegex} is non‑null and non‑empty, return it directly.
     *   </li>
     *   <li>If neither field provides a usable pattern, return a concise, safe default
     *       regex that validates the scheme and ensures the rest of the URL contains
     *       at least one non‑whitespace character.  This default avoids the catastrophic
     *       back‑tracking present in the original massive pattern.
     *   </li>
     * </ol>
     *
     * @return a safe regular expression for URL validation
     */
    public String getUrlRegex() {
        // 1. Prefer the expression supplied via urlRegexExpression
        if (StringUtils.isNotBlank(urlRegexExpression)) {
            try {
                Object parsed = parse(urlRegexExpression, String.class);
                if (parsed instanceof String) {
                    String result = ((String) parsed).trim();
                    if (!result.isEmpty()) {
                        return result;
                    }
                }
                // If parsing does not yield a usable String, fall through to next step
                LOG.log(Level.WARNING, "Parsed urlRegexExpression did not produce a valid non‑empty String.");
            } catch (Exception e) {
                // Parsing failed – log and continue with fallback logic
                LOG.log(Level.WARNING, "Failed to parse urlRegexExpression: " + e.getMessage(), e);
            }
        }

        // 2. Fallback to the plain urlRegex field if it is set
        if (StringUtils.isNotBlank(urlRegex)) {
            return urlRegex.trim();
        }

        // 3. Safe default regex – lightweight and resistant to catastrophic back‑tracking
        //    It validates the scheme (http, https, ftp) and requires at least one
        //    non‑whitespace character after the scheme separator.
        return "^(https?|ftp)://[^\\s]+$";
    }

    // other methods ...

}
