void setTo(Calendar c, int i) {
    if (c == null) {
        throw new IllegalArgumentException("Calendar must not be null");
    }
    // Compute the raw value that will be stored in the Calendar
    int raw = i - offset;

    // Determine the legal bounds for the target field in the current calendar context
    int min = c.getActualMinimum(field);
    int max = c.getActualMaximum(field);

    if (raw < min || raw > max) {
        // The value would cause Calendar to roll over silently, which can lead to
        // infinite adjustment loops in the surrounding algorithm.  We fail fast.
        throw new IllegalArgumentException(
                String.format("Attempt to set field %d to %d (adjusted %d) which is outside the allowed range [%d,%d]",
                        field, i, raw, min, max));
    }

    // Safe to set – the Calendar will not perform any implicit roll‑over.
    c.set(field, raw);
}
