private static final Set<String> ALLOWED_ALGORITHMS = Collections.unmodifiableSet(
        new HashSet<>(Arrays.asList(
                "HS256", "HS384", "HS512",
                "RS256", "RS384", "RS512",
                "ES256", "ES384", "ES512"
        )));

private JWT decode(String encodedJWT, Header header, String[] parts, Verifier verifier) {
    // -----------------------------------------------------------------
    // 1. Validate the JWT header algorithm.
    // -----------------------------------------------------------------
    if (header == null || header.algorithm == null) {
        throw new MissingVerifierException(
                "JWT header is missing or does not contain a signing algorithm");
    }

    String algName = header.algorithm.getName();
    // Reject the insecure 'none' algorithm and any algorithm that is not
    // explicitly whitelisted.
    if (algName == null || "none".equalsIgnoreCase(algName) || !ALLOWED_ALGORITHMS.contains(algName)) {
        throw new MissingVerifierException(
                "Unsupported or insecure signing algorithm [" + algName + "]");
    }

    // -----------------------------------------------------------------
    // 2. Verify that a verifier is present when a signature is expected.
    // -----------------------------------------------------------------
    if (parts.length == 3 && verifier == null) {
        throw new MissingVerifierException(
                "No Verifier has been provided for verifying a signature signed using [" + algName + "]");
    }

    // -----------------------------------------------------------------
    // 3. Detect a mismatch between verifier presence and signature.
    // -----------------------------------------------------------------
    if (parts.length == 2 && verifier != null) {
        throw new InvalidJWTSignatureException();
    }

    // -----------------------------------------------------------------
    // 4. Extract the signing input (header.payload) for verification.
    // -----------------------------------------------------------------
    int index = encodedJWT.lastIndexOf('.');
    byte[] message = encodedJWT.substring(0, index).getBytes(StandardCharsets.UTF_8);

    // -----------------------------------------------------------------
    // 5. Perform signature verification when a signature is present.
    // -----------------------------------------------------------------
    if (parts.length == 3) {
        byte[] signature = base64Decode(parts[2].getBytes(StandardCharsets.UTF_8));
        verifier.verify(header.algorithm, message, signature);
    }

    // -----------------------------------------------------------------
    // 6. Deserialize the payload and enforce standard JWT claims.
    // -----------------------------------------------------------------
    JWT jwt = Mapper.deserialize(
            base64Decode(parts[1].getBytes(StandardCharsets.UTF_8)),
            JWT.class);

    if (jwt.isExpired()) {
        throw new JWTExpiredException();
    }

    if (jwt.isUnavailableForProcessing()) {
        throw new JWTUnavailableForProcessingException();
    }

    return jwt;
}
