                throw new IllegalStateException("Too many encoding errors, possible infinite loop");
            }
            // ensure enough space for worst‑case surrogate encoding
            int needed = estimateIncrementalEncodingSize(enc, 6 * res.length());
            if (needed > out.remaining()) {
