        final CharBuffer cb = CharBuffer.wrap(name);

        // initial output buffer – size is an estimate, will grow if needed
        ByteBuffer out = ByteBuffer.allocate(estimateInitialBufferSize(enc, cb.remaining()));

        // temporary buffer used when we have to encode a surrogate representation
        CharBuffer tmp = CharBuffer.allocate(6);

        // safeguard against pathological inputs that could otherwise cause an endless loop
        final int MAX_ERROR_COUNT = 1000;
        int errorCount = 0;

        while (cb.hasRemaining()) {
            CoderResult res = enc.encode(cb, out, false);

            if (res.isError()) {                     // unmappable or malformed input
                if (++errorCount > MAX_ERROR_COUNT) {
                    throw new IllegalStateException(
                            "Too many encoding errors – possible infinite loop");
                }

                // Ensure we have enough space for the worst‑case surrogate encoding
                int needed = estimateIncrementalEncodingSize(enc, 6 * res.length());
                if (needed > out.remaining()) {
                    out = ZipEncodingHelper.growBufferBy(out, needed - out.remaining());
                }

                // Process each problematic character individually
