                    char ch = cb.get();                     // consume the offending char
                    CharBuffer surrogate = encodeSurrogate(tmp.clear(), ch);
                    out = encodeFully(enc, surrogate, out);
                }
            } else if (res.isOverflow()) {          // output buffer too small
                int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
                out = ZipEncodingHelper.growBufferBy(out, increment);
            } else {
                // Underflow – all input for this iteration has been consumed.
                // Loop will terminate when cb.hasRemaining() becomes false.
            }
        }

        // Flush any remaining encoder state
        CoderResult flush = enc.encode(cb, out, true);
        if (flush.isOverflow()) {                     // very unlikely, but handle gracefully
            out = ZipEncodingHelper.growBufferBy(out,
                    estimateIncrementalEncodingSize(enc, 1));
            enc.encode(cb, out, true);
        }

        out.limit(out.position());
        out.rewind();
        return out;
