/**
 * Interceptor that handles i18n locale selection.
 * <p>
 * The original implementation created a {@link Locale} directly from the request
 * parameter without any validation, which could allow malicious strings (e.g.
 * containing HTML/JS) to be turned into a {@code Locale} and later reflected in
 * the UI, leading to XSS.  The patched version validates the input against a
 * whitelist of acceptable locale patterns and ensures the resulting locale is
 * one of the locales supported by the JVM.
 * </p>
 */
public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /** Set of locale identifiers that the JVM recognises (whitelist). */
    private static final Set<String> SUPPORTED_LOCALES = new HashSet<String>();

    static {
        // Populate the whitelist with all locales the JVM knows about.
        // Using Locale.toString() gives the canonical "language[_country[_variant]]"
        // representation that we later compare against.
        Locale[] available = Locale.getAvailableLocales();
        for (Locale l : available) {
            SUPPORTED_LOCALES.add(l.toString());
        }
    }

    // -----------------------------------------------------------------------
    // other methods
    // -----------------------------------------------------------------------

    /**
     * Creates a {@link Locale} object from the request parameter, which might
     * already be a {@link Locale} or a {@link String}. The input is validated
     * against a strict whitelist to prevent injection attacks.
     *
     * @param requestedLocale the parameter from the request
     * @return a validated {@link Locale} or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        Locale locale = null;

        if (requestedLocale instanceof Locale) {
            // Directly supplied Locale – still verify it is a supported one.
            locale = (Locale) requestedLocale;
        } else {
            // Convert to String and trim whitespace.
            String localeStr = requestedLocale.toString().trim();

            if (localeStr.isEmpty()) {
                LOG.warn("Locale parameter is empty after trimming.");
                return null;
            }

            // -------------------------------------------------------------------
            // Whitelist validation
            // Accept patterns like:
            //   en
            //   en_US
            //   en_US_WIN
            // Language: 2‑3 alphabetic characters (ISO‑639)
            // Country : optional, 2 alphabetic characters (ISO‑3166)
            // Variant : optional, alphanumeric (any length)
            // -------------------------------------------------------------------
            if (!localeStr.matches("^[a-zA-Z]{2,3}(_[a-zA-Z]{2})?(_[a-zA-Z0-9]+)?$")) {
                LOG.warn("Invalid locale format supplied: '{}'. Rejecting.", localeStr);
                return null;
            }

            // At this point the format is safe; let Struts' utility create the Locale.
            locale = LocalizedTextUtil.localeFromString(localeStr, null);
        }

        // -----------------------------------------------------------------------
        // Ensure the resulting Locale is one that the JVM supports.
        // This prevents crafted strings that pass the regex but resolve to a
        // non‑standard Locale (e.g., with unexpected script or variant).
        // -----------------------------------------------------------------------
        if (locale != null && isSupportedLocale(locale)) {
            LOG.debug("Applied request locale: {}", locale);
            return locale;
        } else {
            LOG.warn("Unsupported or unrecognised locale: {}", locale);
            return null;
        }
    }

    /**
     * Checks whether the supplied {@link Locale} is part of the JVM's whitelist.
     *
     * @param locale the locale to check
     * @return {@code true} if the locale is supported
     */
    private static boolean isSupportedLocale(Locale locale) {
        // Locale.toString() yields the same canonical form used in the whitelist.
        return SUPPORTED_LOCALES.contains(locale.toString());
    }

    // -----------------------------------------------------------------------
    // other methods
    // -----------------------------------------------------------------------
}
