                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the target directory to its real (canonical) path once.
        final Path targetDirPath = targetDirectory.toPath().toRealPath().normalize();

        ArchiveEntry nextEntry;
        while ((nextEntry = supplier.getNextReadableEntry()) != null) {
            final String entryName = nextEntry.getName();

            // Defensive: skip null or empty names (should not happen in well‑formed archives).
            if (entryName == null || entryName.isEmpty()) {
                continue;
            }

            // Reject absolute entry names – they would ignore the target directory completely.
            final Path entryPath = Paths.get(entryName);
            if (entryPath.isAbsolute()) {
                throw new IOException("Archive entry has absolute path: " + entryName);
            }

            // Resolve the entry against the target directory and normalise the result.
            final Path resolvedPath = targetDirPath.resolve(entryPath).normalize();

            // Ensure the resolved path is still inside the target directory.
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException(
                    "expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            final File f = resolvedPath.toFile();

