        return -1;
    }

    // Have we already read the whole entry?
    if (current.bytesRead >= entrySize) {
        return -1;
    }

    // Fill the internal buffer if it is empty.  We never read past the declared
    // size of the entry – doing so would corrupt the following entry and could
    // cause an endless stream when the archive is maliciously crafted.
    if (buf.position() >= buf.limit()) {
        buf.clear(); // position = 0, limit = capacity
        // Read at most the remaining bytes of the entry, never more than the buffer capacity.
        int maxToRead = (int) Math.min(buf.capacity(), entrySize - current.bytesRead);
        int read = in.read(buf.array(), 0, maxToRead);
        if (read == -1) {
            // Underlying stream ended before the declared size – treat as EOF.
            return -1;
        }
        buf.limit(read);
        count(read);
        current.bytesReadFromStream += read;
    }

    // Determine how many bytes we can safely return to the caller.
    int toRead = Math.min(buf.remaining(), length);
    long remainingInEntry = entrySize - current.bytesRead;
    if (remainingInEntry < toRead) {
        toRead = (int) remainingInEntry;
    }

    if (toRead <= 0) {
        return -1;
    }

    buf.get(buffer, offset, toRead);
