import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // -----------------------------------------------------------------------
    // Core authorization logic
    // -----------------------------------------------------------------------
    /**
     * Determines whether the incoming request is allowed to update the user
     * identified by the path variable. The method now enforces that the caller is
     * either:
     * <ul>
     *   <li>an administrator (has role {@code admin}), or</li>
     *   <li>the owner of the account (the authenticated user id matches the id
     *   extracted from the request URL).</li>
     * </ul>
     *
     * In addition to the ownership check, the method validates that immutable
     * fields (email, username, origin, verification status, and active flag)
     * have not been altered in the request payload.
     *
     * @param request the incoming HTTP request
     * @return {@code true} if the update is permitted, {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // -------------------------------------------------------------------
        // 1. Authorisation – ensure the caller is allowed to touch this user.
        // -------------------------------------------------------------------
        String authenticatedUserId = getAuthenticatedUserId(request);
        String targetUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // Admins are allowed to modify any user.
        boolean isAdmin = request.isUserInRole("admin");

        // If the caller is not an admin, they must be the owner of the account.
        if (!isAdmin) {
            if (authenticatedUserId == null || !authenticatedUserId.equals(targetUserId)) {
                // Not the owner – deny the request.
                return false;
            }
        }

        // ---------------------------------------------------------------
        // 2. Load the existing user from the database.
        // ---------------------------------------------------------------
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(targetUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot validate the request – deny.
            return false;
        }

        // ---------------------------------------------------------------
        // 3. Parse the incoming payload.
        // ---------------------------------------------------------------
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // ---------------------------------------------------------------
        // 4. Validate immutable fields – they must not change.
        // ---------------------------------------------------------------
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the update is allowed.
        return true;
    }

    // -----------------------------------------------------------------------
    // Helper methods
    // -----------------------------------------------------------------------
    /**
     * Retrieves the authenticated user identifier from the request.
     * <p>
     * The method first checks the {@link Principal} attached to the request.
     * If no principal is present, it falls back to a custom header
     * {@code X-Authenticated-User-Id}. This approach works both with container
     * based authentication and with downstream services that propagate the
     * user id via a header.
     *
     * @param request the incoming HTTP request
     * @return the authenticated user id, or {@code null} if it cannot be
     *         determined
     */
    private String getAuthenticatedUserId(HttpServletRequest request) {
        Principal principal = request.getUserPrincipal();
        if (principal != null) {
            return principal.getName();
        }
        // Fallback – some deployments forward the user id in a header.
        return request.getHeader("X-Authenticated-User-Id");
    }

    // other methods (setters, constructors, etc.) would be here
}
